/// Quantizes a single 16-bit channel value in [0, 65535] to 8-bit [0, 255] using a blue noise threshold rank in [0, 4095].
#[inline(always)]
fn dither_channel_u16_to_u8(v16: u16, threshold_rank: u16) -> u8 {
    let v0 = (v16 / 257) as u8;
    let rem = (v16 % 257) as u32;
    // Fractional comparison: rem / 257.0 > (threshold_rank + 0.5) / 4096.0
    // In exact integer arithmetic: rem * 4096 > threshold_rank * 257 + 128
    let threshold = (threshold_rank as u32) * 257 + 128;
    if rem * 4096 > threshold && v0 < 255 {
        v0 + 1
    } else {
        v0
    }
}

/// Dithers a 16-bit pixmap into an 8-bit pixmap using a 64x64 blue noise matrix with decorrelated channels.
pub fn dither_u16_to_u8(src: &PixmapU16) -> Pixmap {
    let width = src.width();
    let height = src.height();
    let mut dst = Pixmap::new(width, height).expect("failed to allocate 8bpc pixmap");

    let src_pixels: &[PremultipliedColorU16] = src.pixels();
    let dst_pixels: &mut [PremultipliedColorU8] = dst.pixels_mut();

    for y in 0..height {
        let y_idx = (y * width) as usize;
        let y_r = (y & 63) * 64;
        let y_g = ((y + 41) & 63) * 64;
        let y_b = ((y + 17) & 63) * 64;
        let y_a = ((y + 53) & 63) * 64;

        for x in 0..width {
            let sp = src_pixels[y_idx + x as usize];
            let a16 = sp.alpha();

            if a16 == 0 {
                dst_pixels[y_idx + x as usize] = PremultipliedColorU8::TRANSPARENT;
                continue;
            }

            let r_rank = BLUE_NOISE_64[(y_r + (x & 63)) as usize];
            let g_rank = BLUE_NOISE_64[(y_g + ((x + 23) & 63)) as usize];
            let b_rank = BLUE_NOISE_64[(y_b + ((x + 47) & 63)) as usize];
            let a_rank = BLUE_NOISE_64[(y_a + ((x + 31) & 63)) as usize];

            if a16 >= 65534 {
                let r8 = dither_channel_u16_to_u8(sp.red(), r_rank);
                let g8 = dither_channel_u16_to_u8(sp.green(), g_rank);
                let b8 = dither_channel_u16_to_u8(sp.blue(), b_rank);
                dst_pixels[y_idx + x as usize] =
                    PremultipliedColorU8::from_rgba_unchecked(r8, g8, b8, 255);
            } else {
                // Demultiply 16bpc to continuous un-premultiplied color
                let a32 = a16 as u32;
                let un_r = ((sp.red() as u32 * 65535 + a32 / 2) / a32).min(65535) as u16;
                let un_g = ((sp.green() as u32 * 65535 + a32 / 2) / a32).min(65535) as u16;
                let un_b = ((sp.blue() as u32 * 65535 + a32 / 2) / a32).min(65535) as u16;

                let un_r8 = dither_channel_u16_to_u8(un_r, r_rank) as u32;
                let un_g8 = dither_channel_u16_to_u8(un_g, g_rank) as u32;
                let un_b8 = dither_channel_u16_to_u8(un_b, b_rank) as u32;
                let a8 = dither_channel_u16_to_u8(a16, a_rank) as u32;

                // Re-premultiply to 8bpc
                let pr_r8 = ((un_r8 * a8 + 127) / 255) as u8;
                let pr_g8 = ((un_g8 * a8 + 127) / 255) as u8;
                let pr_b8 = ((un_b8 * a8 + 127) / 255) as u8;

                dst_pixels[y_idx + x as usize] =
                    PremultipliedColorU8::from_rgba_unchecked(pr_r8, pr_g8, pr_b8, a8 as u8);
            }
        }
    }

    dst
}

/// Directly downsamples a 16-bit pixmap to an 8-bit pixmap (rounding to nearest 8-bit integer without dithering).
pub fn downsample_u16_to_u8(src: &PixmapU16) -> Pixmap {
    let width = src.width();
    let height = src.height();
    let mut dst = Pixmap::new(width, height).expect("failed to allocate 8bpc pixmap");

    let src_pixels: &[PremultipliedColorU16] = src.pixels();
    let dst_pixels: &mut [PremultipliedColorU8] = dst.pixels_mut();

    for (sp, dp) in src_pixels.iter().zip(dst_pixels.iter_mut()) {
        let r8 = ((sp.red() as u32 * 255 + 32768) / 65535) as u8;
        let g8 = ((sp.green() as u32 * 255 + 32768) / 65535) as u8;
        let b8 = ((sp.blue() as u32 * 255 + 32768) / 65535) as u8;
        let a8 = ((sp.alpha() as u32 * 255 + 32768) / 65535) as u8;
        *dp = PremultipliedColorU8::from_rgba_unchecked(r8, g8, b8, a8);
    }

    dst
}
